 companion object { private const val MODULE="ZaycommBle"; private const val SERVICE="8f4d0001-7e2c-4c7d-9f11-7a9d00000001"; private const val FRAME="8f4d0002-7e2c-4c7d-9f11-7a9d00000001"; private const val CCCD="00002902-0000-1000-8000-00805f9b34fb" }
 private val serviceUuid=UUID.fromString(SERVICE);private val frameUuid=UUID.fromString(FRAME);private val cccdUuid=UUID.fromString(CCCD);private val manager=context.getSystemService(Context.BLUETOOTH_SERVICE) as BluetoothManager;private val adapter:BluetoothAdapter? get()=manager.adapter
 private var scanCallback:ScanCallback?=null;private var advertiser:BluetoothLeAdvertiser?=null;private var server:BluetoothGattServer?=null;private var frameCharacteristic:BluetoothGattCharacteristic?=null;private val gattConnections=mutableMapOf<String,BluetoothGatt>();private val serverClients=mutableMapOf<String,BluetoothDevice>();private val connectingAddresses=mutableSetOf<String>()
 override fun getName()=MODULE
