 private fun connectInternal(address:String,promise:Promise?=null){val bt=adapter;if(bt==null){promise?.let{fail(it,"BLE_UNAVAILABLE","Bluetooth adapter unavailable")};return};if(!bt.isEnabled){promise?.let{fail(it,"BLE_DISABLED","Bluetooth LE unavailable or disabled")};return};if(!allowed(Manifest.permission.BLUETOOTH_CONNECT)){promise?.let{fail(it,"BLE_PERMISSION","Bluetooth connect permission required")};return};if(gattConnections.containsKey(address)||!connectingAddresses.add(address)){promise?.resolve(null);return};val device=try{bt.getRemoteDevice(address)}catch(e:Exception){connectingAddresses.remove(address);promise?.let{fail(it,"BLE_ADDRESS","Invalid Bluetooth address")};return};val gatt=device.connectGatt(context,false,object:BluetoothGattCallback(){override fun onConnectionStateChange(g:BluetoothGatt,status:Int,state:Int){val ok=state==BluetoothProfile.STATE_CONNECTED;if(ok){gattConnections[address]=g;connectingAddresses.remove(address);g.discoverServices()}else{gattConnections.remove(address);connectingAddresses.remove(address);g.close()};emit("ZaycommBleConnectionChanged",Arguments.createMap().apply{putString("address",address);putBoolean("connected",ok)})};override fun onServicesDiscovered(g:BluetoothGatt,status:Int){if(status!=BluetoothGatt.GATT_SUCCESS){promise?.let{fail(it,"BLE_GATT","Service discovery failed: $status")};return};val ch=g.getService(serviceUuid)?.getCharacteristic(frameUuid);if(ch==null){promise?.let{fail(it,"BLE_SERVICE","Zaycomm frame characteristic not found")};return};if(ch.properties and BluetoothGattCharacteristic.PROPERTY_NOTIFY!=0&&g.setCharacteristicNotification(ch,true)){ch.getDescriptor(cccdUuid)?.let{d->if(Build.VERSION.SDK_INT>=33)g.writeDescriptor(d,BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE)else{@Suppress("DEPRECATION")d.value=BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE;@Suppress("DEPRECATION")g.writeDescriptor(d)}}};promise?.resolve(null)};override fun onCharacteristicChanged(g:BluetoothGatt,ch:BluetoothGattCharacteristic){if(ch.uuid==frameUuid)emit("ZaycommBleFrame",Arguments.createMap().apply{putString("address",address);putArray("frame",Arguments.fromList(ch.value.map{it.toInt()}))})}});if(gatt==null){connectingAddresses.remove(address);promise?.let{fail(it,"BLE_CONNECT","Unable to create GATT connection")}}
 @ReactMethod fun startScan(promise:Promise){val bt=adapter;if(bt==null){fail(promise,"BLE_UNAVAILABLE","Bluetooth adapter unavailable");return};if(!bt.isEnabled){fail(promise,"BLE_DISABLED","Bluetooth LE unavailable or disabled");return};if(!allowed(Manifest.permission.BLUETOOTH_SCAN)){fail(promise,"BLE_PERMISSION","Bluetooth scan permission required");return};val scanner=bt.bluetoothLeScanner;if(scanner==null){fail(promise,"BLE_UNAVAILABLE","Bluetooth LE scanner unavailable");return};scanCallback?.let{scanner.stopScan(it)};val cb=object:ScanCallback(){override fun onScanResult(type:Int,result:ScanResult){val record=result.scanRecord?:return;if(record.serviceUuids?.any{it.uuid==serviceUuid}==true){val address=result.device.address;emit("ZaycommBleAdvertisement",Arguments.createMap().apply{putString("id",address);putString("address",address);putString("name",result.device.name)});connectInternal(address)}};override fun onScanFailed(code:Int){emit("ZaycommBleScanError",Arguments.createMap().apply{putInt("code",code)})}};scanCallback=cb;try{scanner.startScan(listOf(ScanFilter.Builder().setServiceUuid(ParcelUuid(serviceUuid)).build()),ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),cb);promise.resolve(null)}catch(e:Exception){fail(promise,"BLE_SCAN",e.message?:"Unable to start BLE scan")}}
 @ReactMethod fun stopScan(){if(!allowed(Manifest.permission.BLUETOOTH_SCAN))return;scanCallback?.let{adapter?.bluetoothLeScanner?.stopScan(it)};scanCallback=null}
 @ReactMethod fun startAdvertising(nodeName:String,promise:Promise){val bt=adapter;if(bt==null){fail(promise,"BLE_UNAVAILABLE","Bluetooth adapter unavailable");return};if(!bt.isEnabled){fail(promise,"BLE_DISABLED","Bluetooth LE unavailable or disabled");return};if(!allowed(Manifest.permission.BLUETOOTH_ADVERTISE)||!allowed(Manifest.permission.BLUETOOTH_CONNECT)){fail(promise,"BLE_PERMISSION","Bluetooth permissions are required");return};val name=nodeName.trim().take(248);if(name.isNotEmpty()){try{bt.name=name}catch(_:Exception){}};val service=BluetoothGattService(serviceUuid,BluetoothGattService.SERVICE_TYPE_PRIMARY);val ch=BluetoothGattCharacteristic(frameUuid,BluetoothGattCharacteristic.PROPERTY_WRITE or BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE or BluetoothGattCharacteristic.PROPERTY_NOTIFY,BluetoothGattCharacteristic.PERMISSION_WRITE);ch.addDescriptor(BluetoothGattDescriptor(cccdUuid,BluetoothGattDescriptor.PERMISSION_READ or BluetoothGattDescriptor.PERMISSION_WRITE));service.addCharacteristic(ch);frameCharacteristic=ch;server?.close();server=manager.openGattServer(context,object:BluetoothGattServerCallback(){override fun onConnectionStateChange(d:BluetoothDevice,status:Int,state:Int){val ok=state==BluetoothProfile.STATE_CONNECTED;if(ok)serverClients[d.address]=d else serverClients.remove(d.address);emit("ZaycommBleConnectionChanged",Arguments.createMap().apply{putString("address",d.address);putBoolean("connected",ok)})};override fun onDescriptorWriteRequest(d:BluetoothDevice,id:Int,desc:BluetoothGattDescriptor,prepared:Boolean,response:Boolean,offset:Int,value:ByteArray){if(desc.uuid==cccdUuid&&response)server?.sendResponse(d,id,BluetoothGatt.GATT_SUCCESS,0,null)};override fun onCharacteristicWriteRequest(d:BluetoothDevice,id:Int,ch:BluetoothGattCharacteristic,prepared:Boolean,response:Boolean,offset:Int,value:ByteArray){if(ch.uuid!=frameUuid||value.size>200)return;emit("ZaycommBleFrame",Arguments.createMap().apply{putString("address",d.address);putArray("frame",Arguments.fromList(value.map{it.toInt()}))});if(response)server?.sendResponse(d,id,BluetoothGatt.GATT_SUCCESS,0,null)}});if(server==null){fail(promise,"BLE_GATT_SERVER","Unable to open GATT server");return};if(!server!!.addService(service)){server?.close();server=null;fail(promise,"BLE_GATT_SERVICE","Unable to register Zaycomm BLE service");return};advertiser=bt.bluetoothLeAdvertiser;if(advertiser==null){server?.close();server=null;fail(promise,"BLE_UNAVAILABLE","BLE advertising is not supported on this device");return};val settings=AdvertiseSettings.Builder().setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY).setConnectable(true).setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_HIGH).build();val data=AdvertiseData.Builder().setIncludeDeviceName(false).addServiceUuid(ParcelUuid(serviceUuid)).build();advertiser!!.startAdvertising(settings,data,object:AdvertiseCallback(){override fun onStartSuccess(x:AdvertiseSettings)=promise.resolve(null);override fun onStartFailure(code:Int){val reason=advertiseFailureReason(code);emit("ZaycommBleAdvertiseError",Arguments.createMap().apply{putInt("code",code);putString("reason",reason);putBoolean("bluetoothEnabled",bt.isEnabled);putBoolean("advertiserAvailable",bt.bluetoothLeAdvertiser!=null);putInt("sdk",Build.VERSION.SDK_INT)});server?.close();server=null;advertiser=null;fail(promise,"BLE_ADVERTISE", "BLE advertising failed: $code ($reason)")}})}
 @ReactMethod fun stopAdvertising(){if(allowed(Manifest.permission.BLUETOOTH_ADVERTISE))advertiser?.stopAdvertising(object:AdvertiseCallback(){});advertiser=null;server?.close();server=null;serverClients.clear()}
 @ReactMethod fun requestEnableBluetooth(){if(!allowed(Manifest.permission.BLUETOOTH_CONNECT))return;context.currentActivity?.let{if(adapter?.isEnabled==false)it.startActivity(Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE))}}
