 @ReactMethod fun disconnect(address:String,promise:Promise){if(!allowed(Manifest.permission.BLUETOOTH_CONNECT)){fail(promise,"BLE_PERMISSION","Bluetooth connect permission required");return};gattConnections.remove(address)?.let{it.disconnect();it.close()};connectingAddresses.remove(address);promise.resolve(null)}
 @ReactMethod fun addListener(eventName:String){};@ReactMethod fun removeListeners(count:Int){}
